        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_list(v):
        if not v:
            return []
        if isinstance(v, dict):
            try:
                return list(v.keys())
            except:
                return []
        try:
