            cy = max(0, gh // 2) if gh else sy
            best = (cx, cy)
        return step_toward(me, best)

    resources = []
    for key in ("resources", "resource_positions", "resource_cells", "food"):
        items = observation.get(key)
        items = safe_list(items)
        if items:
            resources = items
            break

    if resources:
